import {readRates,rateFields,interestPlan} from './debt-interest.js?v=20261025e';
const fmt=n=>n.toLocaleString('en-US',{maximumFractionDigits:2});
export function interestPanel(storage){
 const {rates,error}=readRates(storage),rows=interestPlan(rates);
 const interestTotal=rows.reduce((n,r)=>n+Math.round(r.interestTotal*100),0)/100;
 const cashTotal=rows.reduce((n,r)=>n+Math.round(r.cashTotal*100),0)/100;
 return `<section class="panel debt-interest" aria-labelledby="debt-interest-title"><h2 id="debt-interest-title">ดอกเบี้ยและเงินที่ต้องเตรียมเพิ่ม</h2>
 <p><strong>งบเดิม 15,000 บาทใช้ลดหนี้และจ่ายงวด G · ดอกของเจ้าอื่นหาเพิ่มต่างหากตามที่ตกลง</strong></p>
 <p>G รวมดอกในงวดเดิมแล้ว ไม่บวกซ้ำ · S รวม 7,900 บาท ไม่มีดอกเพิ่ม</p>
 <div class="notice"><strong>ประมาณการ ไม่ใช่ยอดเรียกเก็บ</strong><p>AEON รายการบนยังไม่ทราบประเภท ใช้ 25% ต่อปีสมมติกรณียัวร์แคช · LINE BK ใช้ 25% สำหรับวงเงินปกติ (ช่วง 18–25%; นาโน 33%) · ทองใช้เพดาน 1.25% ต่อเดือน อัตราจริงตามสัญญา · เปลี่ยนให้ตรงบัญชีของคุณด้านล่างได้</p><p>AEON ใช้ยอดชำระเต็มจำนวนจากภาพ 15,115.44 + 10,325.11 = 25,440.55 บาทเป็นฐานประมาณการ ยอดนี้อาจมีดอก/ค่าธรรมเนียมเดิม จึงไม่ใช่เงินต้นที่ยืนยันแล้ว ขั้นต่ำในภาพ 378 + 827 = 1,205 บาทเป็นของงวดนั้น ให้ตรวจใบแจ้งยอดแต่ละเดือน</p></div>
 <form id="debt-rate-form" class="debt-rate-form">${rateFields.map(f=>`<label>${f.name}<span>${f.unit}</span><input id="debt-rate-${f.key}" type="number" inputmode="decimal" min="0" max="${f.max}" step="0.01" value="${rates[f.key]}" required></label>`).join('')}<button class="button secondary" type="submit">บันทึกอัตราและคำนวณใหม่</button></form><p id="debt-rate-error" role="alert" ${error?'':'hidden'}>${error}</p>
 ${error?'<p>ยังไม่แสดงประมาณการจนกว่าจะบันทึกอัตราใหม่</p>':`<p><strong>ดอกเพิ่มเติมทั้งแผนประมาณ ${fmt(interestTotal)} บาท · จ่ายรวมประมาณ ${fmt(cashTotal)} บาท</strong></p><div class="debt-table" tabindex="0" role="region" aria-label="ตารางดอกเบี้ยประมาณการ"><table><thead><tr><th>เดือน</th><th>AEON รายการบน</th><th>AEON เครดิต</th><th>LINE BK</th><th>ทอง</th><th>ดอกเพิ่มรวม</th><th>ยอดแผนเดิม</th><th>เงินจ่ายรวม</th></tr></thead><tbody>${rows.map(r=>`<tr><th scope="row">${r.month}</th>${['aeonUpper','aeonCard','line','gold'].map(k=>`<td>${fmt(r.interest[k])}</td>`).join('')}<td>${fmt(r.interestTotal)}</td><td>${fmt(r.baseTotal)}</td><td><strong>${fmt(r.cashTotal)}</strong></td></tr>`).join('')}</tbody></table></div>`}
 <p class="debt-hint">จำลองรอบละ 30 วัน จ่ายลดหนี้ปลายรอบ ไม่มีการกู้เพิ่ม ดอกรายปี = ยอดต้นรอบ × อัตรา × 30 ÷ 365 ส่วนทอง = ยอดต้นรอบ × อัตรารายเดือน จ่ายดอกแยกทุกงวด ไม่มีดอกค้างทบยอด ประมาณการนี้อิงตารางเป้าหมาย ไม่ใช่ประวัติการจ่ายจริง วันที่จ่ายย่อยจริงทำให้ดอกต่างจากตัวอย่างได้</p>
 <p class="debt-hint">แหล่งอัตราที่ตรวจ 25 ต.ค. 2569: <a href="https://www.aeon.co.th/aeon/personal-loan/yourcash" target="_blank" rel="noopener noreferrer">AEON ยัวร์แคช</a> · <a href="https://www.aeon.co.th/aeon/cards/" target="_blank" rel="noopener noreferrer">AEON เครดิต</a> · <a href="https://www.linebk.com/th/credit-line/" target="_blank" rel="noopener noreferrer">LINE BK</a> · <a href="https://www.aurora.co.th/news/page_news/2166/ขาย-ฝาก-ปลอดภัยกว่าใครที่-ทองมาเงินไป" target="_blank" rel="noopener noreferrer">ทองมาเงินไป / AURORA</a></p></section>`;
}
